"""Legal Stance Playbook — юридическая позиция при составлении договора."""

from __future__ import annotations
from enum import Enum


class LegalStance(str, Enum):
    """
    Юридическая позиция (баланс условий договора).

    PRO_BUYER  — условия максимально защищают Заказчика / Покупателя:
        • Высокие пени Исполнителя, нет потолка
        • Заказчик вправе расторгнуть немедленно
        • Подсудность по месту Заказчика
        • Длительный срок молчаливой приемки (7 дней)

    BALANCED   — сбалансированные условия (умолчание):
        • Симметричные пени 0.1%/день до 10% суммы
        • Расторжение — обе стороны с уведомлением 30 дней
        • Подсудность по месту Истца

    PRO_VENDOR — условия максимально защищают Исполнителя / Поставщика:
        • Низкие пени (1/300 ставки ЦБ), потолок 5%
        • Исполнитель вправе расторгнуть немедленно
        • Подсудность по месту Исполнителя
        • Короткий срок молчаливой приемки (3 дня)
    """
    PRO_BUYER = "PRO_BUYER"
    BALANCED = "BALANCED"
    PRO_VENDOR = "PRO_VENDOR"

    @property
    def label(self) -> str:
        """Human-readable Russian label for UI."""
        return {
            LegalStance.PRO_BUYER: "Pro-Заказчик",
            LegalStance.BALANCED: "Нейтральный",
            LegalStance.PRO_VENDOR: "Pro-Исполнитель",
        }[self]

    @property
    def description(self) -> str:
        return {
            LegalStance.PRO_BUYER: "Максимальная защита интересов Заказчика (высокие пени, подсудность по вашему месту)",
            LegalStance.BALANCED: "Симметричный баланс интересов обеих сторон (рекомендуется)",
            LegalStance.PRO_VENDOR: "Максимальная защита интересов Исполнителя (мягкие пени, быстрая приемка)",
        }[self]
